LIMIT 1`, targetHost).Scan(&n.ID, &n.Name, &n.Host, &n.Port, &n.SSHUser, &n.SSHKeySecretRef, &n.Status)
	if errors.Is(e, sql.ErrNoRows) {
		return Node{}, ErrNoProbe
	}
	if e != nil {

		return Node{}, ErrStore
	}
	return n, nil
}

